-- Index sur molecules.family pour les filtres par famille chimique
CREATE INDEX IF NOT EXISTS idx_molecules_family ON molecules(family);

-- Index sur molecules.chemical_class pour les filtres par classe chimique
CREATE INDEX IF NOT EXISTS idx_molecules_chemical_class ON molecules(chemical_class);

-- Index sur molecules.name pour les recherches par nom (déjà peut-être un index unique)
CREATE INDEX IF NOT EXISTS idx_molecules_name ON molecules(name);

-- Index sur molecules.validation_status pour les filtres de validation
CREATE INDEX IF NOT EXISTS idx_molecules_validation_status ON molecules(validation_status);

-- Index sur tabac_molecule_links.tabac_id pour les JOINs rapides
CREATE INDEX IF NOT EXISTS idx_tabac_molecule_links_tabac_id ON tabac_molecule_links(tabac_id);

-- Index sur tabac_molecule_links.molecule_id pour les JOINs rapides
CREATE INDEX IF NOT EXISTS idx_tabac_molecule_links_molecule_id ON tabac_molecule_links(molecule_id);

-- Index sur synergies.tabac_id pour les filtres par tabac
CREATE INDEX IF NOT EXISTS idx_synergies_tabac_id ON synergies(tabac_id);

-- Index sur synergies.type pour les filtres par type
CREATE INDEX IF NOT EXISTS idx_synergies_type ON synergies(type);

